export async function restoreProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<Project> {
  const row = getDb()
    .update(projects)
    .set(restorePatch())
    .where(and(orgPredicate(projects.orgId, orgId), eq(projects.id, projectId)))
    .returning()
    .get();

  if (!row) throw new Error(`Project ${projectId} not found`);
  return toProject(row);
}

/**
 * Row-level duplicate used by the ops console's "duplicate project" action.
 * Copies the project exactly as it is — status, dates, archive state — under
 * the new name, slug and key; the console renumbers nothing.
 */
export async function duplicateProject(
  orgId: OrgId,
  projectId: ProjectId,
  name: string,
  slug: string,
  key: string,
): Promise<Project> {
  const source = getDb()
    .select()
    .from(projects)
    .where(and(orgPredicate(projects.orgId, orgId), eq(projects.id, projectId)))
    .get();
  if (!source) throw new Error(`Project ${projectId} not found`);

  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(projects)
    .values({
      ...source,
      id: newId(),
      name,
      slug,
      key,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toProject(row);
}

/** Includes archived slugs — a restored project must not collide. */
export async function listTakenProjectSlugs(
  orgId: OrgId,
): Promise<readonly string[]> {
  const rows = getDb()
    .select({ slug: projects.slug })
    .from(projects)
    .where(orgPredicate(projects.orgId, orgId))
    .all();
  return rows.map((row) => row.slug);
}

/** Open/closed/overdue counters plus the last write, for the project card. */
export async function getProjectStats(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<ProjectStats> {
  const db = getDb();
  const scope = and(
    orgPredicate(issues.orgId, orgId),
    eq(issues.projectId, projectId),
    ...compact(livePredicate(issues.archivedAt, {})),
  );

  const closed = db
    .select({ value: count() })
    .from(issues)
    .where(and(scope, inArray(issues.status, [...CLOSED_ISSUE_STATUSES])))
    .get();

  const all = db.select({ value: count() }).from(issues).where(scope).get();

  const overdue = db
    .select({ value: count() })
    .from(issues)
    .where(
      and(
        scope,
        isNotNull(issues.dueAt),
        lt(issues.dueAt, toIsoTimestamp(new Date())),
      ),
    )
    .get();

  const lastActivity = db
    .select({ value: sql<string | null>`max(${issues.updatedAt})` })
  assigneeId: UserId | null,
): Promise<Issue> {
  const row = getDb()
    .update(issues)
    .set({ assigneeId, updatedAt: toIsoTimestamp(new Date()) })
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .returning()
    .get();

  if (!row) throw new Error(`Issue ${issueId} not found`);
  return toIssue(row);
}

export async function archiveIssue(
  orgId: OrgId,
  issueId: IssueId,
): Promise<Issue> {
  const row = getDb()
    .update(issues)
    .set(archivePatch())
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .returning()
    .get();

  if (!row) throw new Error(`Issue ${issueId} not found`);
  return toIssue(row);
}

export async function restoreIssue(
  orgId: OrgId,
  issueId: IssueId,
): Promise<Issue> {
  const row = getDb()
    .update(issues)
    .set(restorePatch())
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .returning()
    .get();

  if (!row) throw new Error(`Issue ${issueId} not found`);
  return toIssue(row);
}

/**
 * Copies a project's issues into another project, row for row, for the ops
 * console's "duplicate project" action: status, assignee and number come
 * along so the duplicate's board matches the original. Labels are copied too.
 */
export async function copyIssuesToProject(
  orgId: OrgId,
  fromProjectId: ProjectId,
  toProjectId: ProjectId,
): Promise<number> {
  const db = getDb();
  const page = await listIssues({
    orgId,
    projectId: fromProjectId,
    limit: 100,
    cursor: null,
  });

  const stamp = toIsoTimestamp(new Date());
  for (const issue of page.items) {
    const id = newId();
    db.insert(issues)
      .values({
        id,
        orgId,
        projectId: toProjectId,
        number: issue.number,
        title: issue.title,
        description: issue.description,
        status: issue.status,
        priority: issue.priority,
        authorId: issue.authorId,
        assigneeId: issue.assigneeId,
        parentId: null,
        estimate: issue.estimate,
        dueAt: issue.dueAt,
        startedAt: issue.startedAt,
        completedAt: issue.completedAt,
        createdAt: stamp,
        updatedAt: stamp,
      })
      .run();

    if (issue.labelIds.length > 0) {
      db.insert(issueLabels)
        .values(
          issue.labelIds.map((labelId) => ({ orgId, issueId: id, labelId })),
        )
        .run();
    }
  }

  return page.items.length;
}

/** Cascade behind `ProjectService.archiveProject`; returns the row count. */
export async function archiveIssuesForProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const rows = getDb()
    .update(issues)
    .set(archivePatch())
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.projectId, projectId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .returning({ id: issues.id })
    .all();

  return rows.length;
}

/** Live, still-open issues whose due date has passed. Drives the overdue job. */
export async function listOverdueIssues(
  orgId: OrgId,
  now: IsoTimestamp,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          livePredicate(issues.archivedAt, {}),
          isNotNull(issues.dueAt),
          lt(issues.dueAt, now),
          inArray(issues.status, ["backlog", "todo", "in_progress", "in_review"]),
        ),
      ),
    )
    .orderBy(issues.dueAt)
/**
 * Recomputes the usage counters that every `LimitCheck` compares against.
 *
 * Must call (do not reimplement): assertOrgScope, subscribe, getPlanLimits
 */
import { getPlanLimits } from "@/config/plan-limits";
import { emit, subscribe } from "@/lib/event-bus";
import { assertOrgScope } from "@/lib/tenant";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { toIsoTimestamp } from "@/types/common";
import type { OrgId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Actor } from "@/types/member";
import type { OrganizationUsage } from "@/types/organization";

/** Fraction of a quota at which the "approaching limit" event fires. */
const WARN_THRESHOLD = 0.9;

export async function getUsage(
  actor: Actor,
  orgId: OrgId,
): Promise<OrganizationUsage> {
  assertOrgScope(actor, orgId);
  return usageRepo.getUsage(orgId);
}

/**
 * Full recount from the source tables. Called by the rollup job and by every
 * event that could have moved a counter — after recounting, the seat and
 * project totals are checked against the plan so a breach surfaces as an
 * event rather than waiting for the next write to be rejected.
 */
export async function recomputeUsage(
  orgId: OrgId,
): Promise<OrganizationUsage> {
  const usage = await usageRepo.recomputeUsage(orgId);
  const org = await orgRepo.findOrgById(orgId);
  if (!org) return usage;

  const limits = getPlanLimits(org.plan);

  if (usage.seatsUsed >= limits.seats * WARN_THRESHOLD) {
    await emit("billing.limit_exceeded", {
      orgId,
      actorId: null,
      occurredAt: toIsoTimestamp(new Date()),
      resource: "seats",
      limit: limits.seats,
      used: usage.seatsUsed,
    });
  }

  if (usage.projectsUsed >= limits.projects * WARN_THRESHOLD) {
    await emit("billing.limit_exceeded", {
      orgId,
      actorId: null,
      occurredAt: toIsoTimestamp(new Date()),
      resource: "projects",
      limit: limits.projects,
      used: usage.projectsUsed,
    });
  }

  return usage;
}

/**
 * Every event that changes a counted resource nudges the cache. The deltas are
 * cheap; the periodic rollup is what corrects any drift they accumulate.
 */
export function registerUsageListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("issue.created", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { issuesUsed: 1 });
    }),
    subscribe("issue.archived", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { issuesUsed: -1 });
    }),
    subscribe("project.created", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { projectsUsed: 1 });
    }),
    subscribe("project.archived", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, {
        projectsUsed: -1,
        issuesUsed: -payload.issuesArchived,
      });
    }),
    subscribe("member.joined", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { seatsUsed: 1 });
    }),
    subscribe("member.removed", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { seatsUsed: -1 });
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}
