/**
 * Fresh-start copy of the source's live issues: numbered from 1 in source
 * order, default status, unassigned, no progress timestamps, authored by
 * `authorId`. Title, description, priority, estimate, due date and labels stay.
 */
export async function cloneIssuesIntoProject(
  orgId: OrgId,
  sources: readonly Issue[],
  toProjectId: ProjectId,
  status: IssueStatus,
  authorId: UserId,
): Promise<number> {
  const db = getDb();
  const stamp = toIsoTimestamp(new Date());
  let number = 0;
  for (const issue of sources) {
    number += 1;
    const id = newId();
    db.insert(issues)
      .values({
        id,
        orgId,
        projectId: toProjectId,
        number,
        title: issue.title,
        description: issue.description,
        status,
        priority: issue.priority,
        authorId,
        assigneeId: null,
        parentId: null,
        estimate: issue.estimate,
        dueAt: issue.dueAt,
        startedAt: null,
        completedAt: null,
        createdAt: stamp,
        updatedAt: stamp,
      })
      .run();

    if (issue.labelIds.length > 0) {
      db.insert(issueLabels)
        .values(
          issue.labelIds.map((labelId) => ({ orgId, issueId: id, labelId })),
        )
        .run();
    }
  }
  return number;
}

