  );

  const used = await projectRepo.countProjects(input.orgId);
  if (wouldExceedLimit(org.plan, "projects", used)) {
    throw new Error(
      `Plan ${org.plan} allows ${used} projects; upgrade to add another`,
    );
  }

  const sources = input.includeIssues
    ? await issueRepo.listLiveIssuesForProject(input.orgId, source.id)
    : [];
  if (
    sources.length > 0 &&
    wouldExceedLimit(org.plan, "issuesPerProject", 0, sources.length)
  ) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${input.key}`,
    );
  }

  const slug = await suggestProjectSlug(input.orgId, input.slug);
  const project = await projectRepo.insertProjectClone(
    source,
    input.name,
    slug,
    input.key,
  );

  const parsedStatus = issueStatusSchema.safeParse(org.settings.defaultIssueStatus);
  const issuesCopied = await issueRepo.cloneIssuesIntoProject(
    input.orgId,
    sources,
    project.id,
    parsedStatus.success ? parsedStatus.data : "backlog",
    actor.userId,
  );

  await emit("project.cloned", {
    ...actorEnvelope(actor),
    projectId: project.id,
    sourceProjectId: source.id,
    issuesCopied,
  });

  return project;
}

